package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// SalesRec - 01 SALES-REC, 12 bytes
type SalesRec struct {
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

// working-storage package-level variables
var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.Zero
var WsTotal decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var CurrentSalesRec SalesRec

// tier table OCCURS 4
type tierEntry struct {
	TierLimit decimal.Decimal
	TierRate  decimal.Decimal
}

var tierEntries [4]tierEntry

// file handling
var fileLines []string
var filePos int

func readFileLines(path string) []string {
	f, err := os.Open(path)
	if err != nil {
		return []string{}
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// keep default split ScanLines which preserves spaces
	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	return lines
}

// fitDecimal keeps low-order integer digits that fit (high-order silently dropped)
func fitDecimal(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	signNegative := val.Sign() < 0
	absVal := val.Abs()
	s := absVal.StringFixed(scale)
	parts := strings.Split(s, ".")
	intPart := parts[0]
	fracPart := ""
	if scale > 0 {
		if len(parts) > 1 {
			fracPart = parts[1]
		} else {
			fracPart = strings.Repeat("0", int(scale))
		}
		if len(fracPart) < int(scale) {
			fracPart += strings.Repeat("0", int(scale)-len(fracPart))
		} else if len(fracPart) > int(scale) {
			fracPart = fracPart[:scale]
		}
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	var newStr string
	if scale > 0 {
		newStr = intPart + "." + fracPart
	} else {
		newStr = intPart
	}
	if newStr == "" {
		newStr = "0"
	}
	if scale > 0 && strings.HasPrefix(newStr, ".") {
		newStr = "0" + newStr
	}
	newVal, _ := decimal.NewFromString(newStr)
	if signNegative {
		newVal = newVal.Neg()
	}
	return newVal
}

func formatInt(v int64, digits int) string {
	s := strconv.FormatInt(v, 10)
	// handle negative - keep sign? not needed for positive counts
	if v < 0 {
		// for negative, keep sign and apply to magnitude
		// high-order drop on magnitude
		sign := "-"
		mag := s[1:]
		if len(mag) > digits {
			mag = mag[len(mag)-digits:]
		} else if len(mag) < digits {
			mag = strings.Repeat("0", digits-len(mag)) + mag
		}
		return sign + mag
	}
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	scale := 0
	intDigitCount := 0
	if dotIdx >= 0 {
		for i := dotIdx + 1; i < len(pic); i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				scale++
			}
		}
		for i := 0; i < dotIdx; i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				intDigitCount++
			}
		}
	} else {
		for i := 0; i < len(pic); i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				intDigitCount++
			}
		}
	}
	absVal := val.Abs()
	// rounding as MOVE would not round but values already have correct scale
	sFixed := absVal.Round(int32(scale)).StringFixed(int32(scale))
	parts := strings.Split(sFixed, ".")
	intPart := parts[0]
	fracPart := ""
	if scale > 0 {
		if len(parts) > 1 {
			fracPart = parts[1]
		} else {
			fracPart = strings.Repeat("0", scale)
		}
		if len(fracPart) < scale {
			fracPart += strings.Repeat("0", scale-len(fracPart))
		} else if len(fracPart) > scale {
			fracPart = fracPart[:scale]
		}
	}
	if len(intPart) > intDigitCount {
		intPart = intPart[len(intPart)-intDigitCount:]
	}
	if len(intPart) < intDigitCount {
		intPart = strings.Repeat("0", intDigitCount-len(intPart)) + intPart
	}
	// map digits to picture
	out := make([]byte, len(pic))
	digitIdx := 0
	fracIdx := 0
	for i := 0; i < len(pic); i++ {
		c := pic[i]
		if c == 'Z' || c == '9' {
			if dotIdx >= 0 && i < dotIdx {
				out[i] = intPart[digitIdx]
				digitIdx++
			} else if dotIdx >= 0 && i > dotIdx {
				out[i] = fracPart[fracIdx]
				fracIdx++
			} else if dotIdx == -1 {
				out[i] = intPart[digitIdx]
				digitIdx++
			}
		} else if c == ',' || c == '.' {
			out[i] = byte(c)
		} else {
			out[i] = byte(c)
		}
	}
	// Z suppression for integer part
	suppressionActive := true
	// scan integer part left to right
	limit := len(pic)
	if dotIdx >= 0 {
		limit = dotIdx
	}
	for i := 0; i < limit; i++ {
		c := pic[i]
		if c == 'Z' || c == '9' {
			dc := out[i]
			if suppressionActive {
				if dc != '0' {
					suppressionActive = false
				} else {
					if c == '9' {
						suppressionActive = false
					} else {
						out[i] = ' '
					}
				}
			}
		} else if c == ',' {
			if suppressionActive {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		}
	}
	return string(out)
}

func InitPara() {
	tierEntries[0].TierLimit = decimal.RequireFromString("1000.00")
	tierEntries[0].TierRate = decimal.RequireFromString("2.50")
	tierEntries[1].TierLimit = decimal.RequireFromString("5000.00")
	tierEntries[1].TierRate = decimal.RequireFromString("4.00")
	tierEntries[2].TierLimit = decimal.RequireFromString("20000.00")
	tierEntries[2].TierRate = decimal.RequireFromString("5.50")
	tierEntries[3].TierLimit = decimal.RequireFromString("999999.99")
	tierEntries[3].TierRate = decimal.RequireFromString("7.25")
}

func ReadPara() {
	if filePos >= len(fileLines) {
		WsEofFlag = "Y"
		return
	}
	line := fileLines[filePos]
	filePos++
	// pad / truncate to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	CurrentSalesRec.SrId = line[0:4]
	salesStr := line[4:12]
	trimmed := strings.TrimSpace(salesStr)
	var n int64 = 0
	if trimmed != "" {
		// sales field is digits only, may have leading zeros
		// ParseInt handles it
		v, err := strconv.ParseInt(trimmed, 10, 64)
		if err == nil {
			n = v
		} else {
			// if contains non-digit, try to extract digits
			// fallback to 0
			n = 0
		}
	}
	CurrentSalesRec.SrSales = decimal.New(n, -2)
}

func ProcessPara() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && WsTier == 0; WsIdx++ {
		if CurrentSalesRec.SrSales.Cmp(tierEntries[WsIdx-1].TierLimit) <= 0 {
			WsTier = WsIdx
		}
	}
	// tier is guaranteed 1..4
	rate := tierEntries[WsTier-1].TierRate
	prod := CurrentSalesRec.SrSales.Mul(rate)
	divided := prod.Shift(-2)
	rounded := divided.Round(2)
	WsComm = fitDecimal(rounded, 6, 2)
	WsTotal = WsTotal.Add(WsComm)
	WsTotal = fitDecimal(WsTotal, 9, 2)
	WsCount++
	if WsCount >= 1000 {
		WsCount = WsCount % 1000
	}
	WsSalesEd = formatEdited(CurrentSalesRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatEdited(rate, "9.99")
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")
	wsTierStr := formatInt(WsTier, 1)
	srIdStr := CurrentSalesRec.SrId
	if len(srIdStr) < 4 {
		srIdStr = srIdStr + strings.Repeat(" ", 4-len(srIdStr))
	} else if len(srIdStr) > 4 {
		srIdStr = srIdStr[:4]
	}
	line := srIdStr + " T" + wsTierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	fmt.Printf("%s\n", line)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	wsCountStr := formatInt(WsCount, 3)
	fmt.Printf("REPS: %s TOTAL: %s\n", wsCountStr, WsTotalEd)
}

func MainPara() {
	InitPara()
	fileLines = readFileLines("input.dat")
	filePos = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	MainPara()
}
